<?php if(!$result['rows']):?><p>Microsoft returned an empty list for this query. Other folders, periods or services may still contain data.</p><?php else:?><div class="ms-results"><table><thead><tr><?php foreach($result['columns']as$label):?><th scope="col"><?=e($label)?></th><?php endforeach;?></tr></thead><tbody><?php foreach($result['rows']as$row):?><tr><?php foreach(array_keys($result['columns'])as$key):?><td><?=e($row[$key])?></td><?php endforeach;?></tr><?php endforeach;?></tbody></table></div><?php endif;?><p><?=!empty($result['more'])?'More items exist. This check displays the first 20 only.':'This is a bounded API result, not a full account export.'?></p>
